/**
 * Lightweight App.js Mobile Navigation & Controller Runtime
 * Compatible with Cordova + App.js (App.controller, App.load, App.back)
 */
(function(window) {
    var controllers = {};
    var historyStack = [];
    var currentPageId = null;

    var App = {
        controller: function(name, fn) {
            controllers[name] = fn;
        },
        load: function(pageName, args) {
            var template = document.querySelector('.app-page[data-page="' + pageName + '"]');
            if (!template) {
                console.error('Page not found:', pageName);
                return;
            }
            document.querySelectorAll('.app-page').forEach(function(el) {
                el.classList.remove('active-page');
            });
            template.classList.add('active-page');
            if (currentPageId && currentPageId !== pageName) {
                historyStack.push(currentPageId);
            }
            currentPageId = pageName;
            if (controllers[pageName]) {
                controllers[pageName](template, args || {});
            }
            window.scrollTo(0, 0);
        },
        back: function(fallbackPage) {
            if (historyStack.length > 0) {
                var prev = historyStack.pop();
                currentPageId = null;
                App.load(prev);
            } else if (fallbackPage) {
                App.load(fallbackPage);
            }
        }
    };

    window.App = App;
})(window);
